export function Campo({ nome, titulo, children, dica }: { nome: string; titulo: string; children: ReactNode; dica?: string }) {
  return <div className="campo"><label htmlFor={nome}>{titulo}</label>{children}{dica && <small id={`${nome}-dica`}>{dica}</small>}</div>;
}

export function Seletor<T extends { id: number }>({ nome, titulo, itens, rotulo, valor, padrao = "", aoMudar, obrigatorio = true, vazio = "Selecione uma opção" }: {
  nome: string; titulo: string; itens: T[]; rotulo: (item: T) => string; valor?: string; padrao?: string; aoMudar?: (valor: string) => void; obrigatorio?: boolean; vazio?: string;
}) {
  return <Campo nome={nome} titulo={titulo}>
    <select id={nome} name={nome} required={obrigatorio} value={valor} onChange={aoMudar ? (e) => aoMudar(e.target.value) : undefined} defaultValue={valor === undefined ? padrao : undefined}>
      <option value="">{vazio}</option>
      {itens.map((item) => <option key={item.id} value={item.id}>{rotulo(item)}</option>)}
    </select>
  </Campo>;
}

export function Carregamento({ carregando, erro }: { carregando: boolean; erro: string }) {
  return <>{carregando && <p className="dica" role="status">Carregando…</p>}<Avisos erro={erro} /></>;
}

export function Tabela({ titulo, children }: { titulo: string; children: ReactNode }) {
  return <div className="resultado-busca" role="region" aria-label={titulo} tabIndex={0}><table>{children}</table></div>;
}

/** O termo fica na URL: recarregar ou voltar preserva a consulta. */
export function Busca({ dica, titulo = "Termo de busca" }: { dica: string; titulo?: string }) {
  const [params, setParams] = useSearchParams();
  const termo = params.get("q") ?? "";
  function buscar(evento: FormEvent<HTMLFormElement>) {
    evento.preventDefault();
    const q = String(new FormData(evento.currentTarget).get("q") ?? "").trim();
    setParams(q ? { q } : {});
  }
  return <form className="busca" onSubmit={buscar}>
    <Campo nome="q" titulo={titulo}><input key={termo} id="q" name="q" defaultValue={termo} placeholder={dica} /></Campo>
    <button type="submit">Buscar</button>
  </form>;
}

export function Acoes({ editar, excluir }: { editar?: string; excluir?: string }) {
  return <span className="acoes">{editar && <Link to={editar}>Editar</Link>}{excluir && <Link to={excluir}>Excluir</Link>}</span>;
}

/** Edição sempre escolhe um registro existente; nenhum ID precisa ser digitado. */
export function FormularioRegistro<T extends { id: number }>({ endpoint, editar = false, rotulo, campos, montar, sucesso, retorno, acao, aviso }: {
  endpoint: string; editar?: boolean; rotulo: (item: T) => string; campos: (item: T | null) => ReactNode; montar: (dados: FormData) => unknown; sucesso: (item: T) => string; retorno: string; acao: string; aviso?: string;
}) {
  const [params, setParams] = useSearchParams();
  const id = params.get("id") ?? "";
  const [revisao, setRevisao] = useState(0);
  const consulta = useDados<T[]>(editar ? endpoint : null, revisao);
  const escolhido = consulta.dados?.find((item) => String(item.id) === id) ?? null;
  const [erro, setErro] = useState("");
  const [mensagem, setMensagem] = useState("");
  const [enviando, setEnviando] = useState(false);
  async function gravar(evento: FormEvent<HTMLFormElement>) {
    evento.preventDefault();
    const formulario = evento.currentTarget;
    const dados = new FormData(formulario);
    setEnviando(true); setErro(""); setMensagem("");
    try {
      const item = await enviar<T>(editar ? `${endpoint}/${id}` : endpoint, editar ? "PUT" : "POST", montar(dados));
      setMensagem(sucesso(item));
      if (editar) setRevisao((valor) => valor + 1); else formulario.reset();
    } catch (e) { setErro((e as Error).message); }
    finally { setEnviando(false); }
  }
  return <>
    {editar && <>
      <Carregamento carregando={consulta.carregando} erro={consulta.erro} />
      {consulta.dados && <div className="selecao-registro"><Seletor nome="registroSelecionado" titulo="Registro para editar" itens={consulta.dados} rotulo={rotulo} valor={id} aoMudar={(valor) => { setParams(valor ? { id: valor } : {}); setErro(""); setMensagem(""); }} />{!consulta.dados.length && <p className="dica">Nenhum registro cadastrado.</p>}</div>}
    </>}
    {(!editar || escolhido) && <form key={`${id}-${revisao}`} className="cadastro" onSubmit={gravar}>
      {campos(escolhido)}
      {aviso && <p className="nota">{aviso}</p>}
      <button disabled={enviando} type="submit">{enviando ? "Salvando…" : acao}</button>
    </form>}
    <Avisos erro={erro} sucesso={mensagem} />
    <p className="rodape-formulario"><Link to={retorno}>Voltar à consulta</Link></p>
  </>;
}

export function ExclusaoRegistro<T extends { id: number }>({ endpoint, rotulo, retorno, aviso }: { endpoint: string; rotulo: (item: T) => string; retorno: string; aviso: string }) {
  const [params, setParams] = useSearchParams();
  const id = params.get("id") ?? "";
  const [revisao, setRevisao] = useState(0);
  const consulta = useDados<T[]>(endpoint, revisao);
  const escolhido = consulta.dados?.find((item) => String(item.id) === id);
  const [erro, setErro] = useState("");
  const [mensagem, setMensagem] = useState("");
  const [enviando, setEnviando] = useState(false);
  async function excluir(evento: FormEvent<HTMLFormElement>) {
    evento.preventDefault();
    setEnviando(true); setErro(""); setMensagem("");
    try {
      await api<void>(`${endpoint}/${id}`, { method: "DELETE" });
      setMensagem("Registro excluído com sucesso."); setParams({}); setRevisao((valor) => valor + 1);
    } catch (e) { setErro((e as Error).message); }
    finally { setEnviando(false); }
  }
  return <>
    <Carregamento carregando={consulta.carregando} erro={consulta.erro} />
    {consulta.dados && <div className="selecao-registro"><Seletor nome="registroSelecionado" titulo="Registro para excluir" itens={consulta.dados} rotulo={rotulo} valor={id} aoMudar={(valor) => { setParams(valor ? { id: valor } : {}); setErro(""); setMensagem(""); }} />{!consulta.dados.length && <p className="dica">Nenhum registro cadastrado.</p>}</div>}
    {escolhido && <form key={id} className="cadastro" onSubmit={excluir}>
      <p className="nota">{aviso}</p>
      <label className="confirmacao"><input type="checkbox" name="confirmacao" required /> Confirmo a exclusão de {rotulo(escolhido)}.</label>
      <button className="perigo" type="submit" disabled={enviando}>{enviando ? "Excluindo…" : "Excluir definitivamente"}</button>
    </form>}
    <Avisos erro={erro} sucesso={mensagem} />
    <p className="rodape-formulario"><Link to={retorno}>Voltar à consulta</Link></p>
  </>;
}

import { useState, type FormEvent, type ReactNode } from "react";
import { Link, useSearchParams } from "react-router-dom";
import { enviar, formatarCpf, type Exemplar, type Leitor } from "../api.ts";
import { Avisos, Campo, Carregamento, Seletor, useDados } from "./biblioteca.tsx";

export function FiltrosCirculacao({ situacoes }: { situacoes: { valor: string; nome: string }[] }) {
  const [params, setParams] = useSearchParams();
  const leitores = useDados<Leitor[]>("/api/leitores");
  const exemplares = useDados<Exemplar[]>("/api/exemplares");
  function filtrar(evento: FormEvent<HTMLFormElement>) {
    evento.preventDefault();
    const dados = new FormData(evento.currentTarget);
    const novos = new URLSearchParams();
    for (const chave of ["leitorId", "exemplarId", "situacao"]) { const valor = String(dados.get(chave) ?? ""); if (valor) novos.set(chave, valor); }
    setParams(novos);
  }
  return <>
    <form className="filtros" onSubmit={filtrar} key={params.toString()}>
      {leitores.dados && <Seletor nome="leitorId" titulo="Leitor" itens={leitores.dados} rotulo={(leitor) => `${leitor.nome} · ${formatarCpf(leitor.cpf)}`} padrao={params.get("leitorId") ?? ""} obrigatorio={false} vazio="Todos os leitores" />}
      {exemplares.dados && <Seletor nome="exemplarId" titulo="Exemplar" itens={exemplares.dados} rotulo={(exemplar) => `${exemplar.numeroRegistro} · ${exemplar.titulo}`} padrao={params.get("exemplarId") ?? ""} obrigatorio={false} vazio="Todos os exemplares" />}
      <Campo nome="situacao" titulo="Situação"><select id="situacao" name="situacao" defaultValue={params.get("situacao") ?? ""}><option value="">Todas</option>{situacoes.map((situacao) => <option key={situacao.valor} value={situacao.valor}>{situacao.nome}</option>)}</select></Campo>
      <button type="submit">Filtrar</button>
    </form>
    <Avisos erro={leitores.erro || exemplares.erro} />
  </>;
}

/** Cancelamento e devolução trabalham com operações existentes, nunca com IDs digitados. */
export function AcaoCirculacao<T extends { id: number }>({ endpoint, sufixo, rotulo, detalhes, acao, sucesso, retorno, vazio }: {
  endpoint: string; sufixo: string; rotulo: (item: T) => string; detalhes: (item: T) => ReactNode; acao: string; sucesso: (item: T) => string; retorno: string; vazio: string;
}) {
  const [params, setParams] = useSearchParams();
  const id = params.get("id") ?? "";
  const [revisao, setRevisao] = useState(0);
  const consulta = useDados<T[]>(sufixo === "cancelamento" ? `${endpoint}?situacao=ativa` : endpoint, revisao);
  // Um empréstimo atrasado continua aberto e também precisa permitir devolução.
  const itens = consulta.dados?.filter((item) => sufixo === "cancelamento" || ("dataDevolucao" in item && item.dataDevolucao === null));
  const escolhido = itens?.find((item) => String(item.id) === id);
  const [erro, setErro] = useState("");
  const [mensagem, setMensagem] = useState("");
  const [enviando, setEnviando] = useState(false);
  async function executar(evento: FormEvent<HTMLFormElement>) {
    evento.preventDefault(); setEnviando(true); setErro(""); setMensagem("");
    try {
      const item = await enviar<T>(`${endpoint}/${id}/${sufixo}`, "POST");
      setMensagem(sucesso(item)); setParams({}); setRevisao((valor) => valor + 1);
    } catch (e) { setErro((e as Error).message); }
    finally { setEnviando(false); }
  }
  return <>
    <Carregamento carregando={consulta.carregando} erro={consulta.erro} />
    {itens && (itens.length ? <div className="selecao-registro"><Seletor nome="operacaoSelecionada" titulo={sufixo === "cancelamento" ? "Reserva ativa" : "Empréstimo em aberto"} itens={itens} rotulo={rotulo} valor={id} aoMudar={(valor) => { setParams(valor ? { id: valor } : {}); setErro(""); setMensagem(""); }} /></div> : <p className="vazio">{vazio}</p>)}
    {escolhido && <form className="cadastro" onSubmit={executar} key={id}>
      <div className="resumo-operacao">{detalhes(escolhido)}</div>
      <label className="confirmacao"><input type="checkbox" name="confirmacao" required /> Confirmo os dados desta operação.</label>
      <button type="submit" disabled={enviando}>{enviando ? "Registrando…" : acao}</button>
    </form>}
    <Avisos erro={erro} sucesso={mensagem} />
    <p className="rodape-formulario"><Link to={retorno}>Voltar à consulta</Link></p>
  </>;
}

import { Link, NavLink, Navigate, Route, Routes, useLocation } from "react-router-dom";
import BuscarLivros from "./pages/BuscarLivros.tsx";
import CadastrarLivro from "./pages/CadastrarLivro.tsx";
import type { PaginaCasoUso } from "./components/biblioteca.tsx";

// Cada aluno acrescenta seu arquivo ucXX.tsx; não há menu ou roteador para disputar.
const modulos = import.meta.glob<{ default: PaginaCasoUso }>("./use-cases/uc[0-9][0-9].tsx", { eager: true });
const paginas = Object.values(modulos).map((modulo) => modulo.default).sort((a, b) => a.id.localeCompare(b.id));
const grupos = [
  { caminho: "/livros", titulo: "Livros" },
  { caminho: "/autores", titulo: "Autores" },
  { caminho: "/leitores", titulo: "Leitores" },
  { caminho: "/exemplares", titulo: "Exemplares" },
  { caminho: "/reservas", titulo: "Reservas" },
  { caminho: "/emprestimos", titulo: "Empréstimos" },
];

export default function App() {
  const localizacao = useLocation();
  const caminhoAtual = localizacao.pathname === "/" || localizacao.pathname === "/cadastrar" ? "/livros" : localizacao.pathname;
  const grupoAtual = grupos.find((grupo) => caminhoAtual.startsWith(grupo.caminho));
  const atividades = paginas.filter((pagina) => pagina.caminho.startsWith(grupoAtual?.caminho ?? "/livros"));
  const temBuscaLivros = paginas.some((pagina) => pagina.id === "uc02");
  const temCadastroLivro = paginas.some((pagina) => pagina.id === "uc01");
  return (
    <>
      <a className="pular-conteudo" href="#conteudo">Ir para o conteúdo</a>
      <header className="topo">
        <div className="identidade"><Link className="marca" to="/">Biblioteca</Link><span>Acervo e circulação</span></div>
        <nav aria-label="Áreas da biblioteca">
          {grupos.filter((grupo) => grupo.caminho === "/livros" || paginas.some((pagina) => pagina.caminho.startsWith(grupo.caminho))).map((grupo) => {
            const inicio = paginas.find((pagina) => pagina.caminho === grupo.caminho)?.caminho ?? paginas.find((pagina) => pagina.caminho.startsWith(grupo.caminho))?.caminho ?? "/";
            return <Link key={grupo.caminho} to={inicio} className={grupoAtual?.caminho === grupo.caminho ? "active" : ""} aria-current={grupoAtual?.caminho === grupo.caminho ? "true" : undefined}>{grupo.titulo}</Link>;
          })}
        </nav>
      </header>
      <div className="faixa-atividades">
        <nav className="atividades" aria-label={`Atividades de ${grupoAtual?.titulo ?? "livros"}`}>
          {atividades.map((pagina) => <NavLink key={pagina.id} to={pagina.caminho} end>{pagina.titulo}</NavLink>)}
          {!temBuscaLivros && grupoAtual?.caminho === "/livros" && <NavLink to="/" end>Buscar livros</NavLink>}
          {!temCadastroLivro && grupoAtual?.caminho === "/livros" && <NavLink to="/cadastrar">Cadastrar livro</NavLink>}
        </nav>
      </div>
      <main className="conteudo" id="conteudo">
        <Routes>
          {paginas.map(({ id, caminho, Componente }) => <Route key={id} path={caminho} element={<Componente />} />)}
          <Route path="/" element={temBuscaLivros ? <Navigate to={`/livros${localizacao.search}`} replace /> : <BuscarLivros />} />
          <Route path="/cadastrar" element={temCadastroLivro ? <Navigate to={`/livros/cadastrar${localizacao.search}`} replace /> : <CadastrarLivro />} />
          <Route path="*" element={<><h1>Página não encontrada</h1><p>Use o menu para escolher uma atividade disponível.</p><Link to="/">Voltar ao acervo</Link></>} />
        </Routes>
      </main>
      <footer className="rodape">Biblioteca · Gestão do acervo e atendimento ao leitor</footer>
    </>
  );
}

